import itertools
def block(g,r0,c0,h,w): return [row[c0:c0+w] for row in g[r0:r0+h]]
def cells(b): return {(r,c) for r in range(len(b)) for c in range(len(b[0])) if b[r][c]!=3}
def norm(cs):
    mr=min(r for r,c in cs); mc=min(c for r,c in cs)
    return frozenset((r-mr,c-mc) for r,c in cs)
