print(t[5][18], t[13][18])

def comps(g):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=3 and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); cs=[]
                while st:
                    a,b=st.pop(); cs.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            p,q=a+da,b+db
                            if 0<=p<h and 0<=q<w and g[p][q]!=3 and (p,q) not in seen:
                                seen.add((p,q)); st.append((p,q))
                out.append(cs)
    return out
